def mache_gruss(gruss):
    def innen(name):
        return f"{gruss}, {name}!"
    return innen          # Funktion zurückgeben, NICHT aufrufen

servus = mache_gruss("Servus")
print(servus("Lea"))     # Servus, Lea!

def protokoll(func):
    def wrapper():
        print("Start")
        func()
        print("Ende")
    return wrapper

def hallo():
    print("Hallo!")

hallo = protokoll(hallo)   # hallo einpacken
hallo()
# Start
# Hallo!
# Ende

import functools

def protokoll(func):
    @functools.wraps(func)          # behält Name und Doku der Originalfunktion
    def wrapper(*args, **kwargs):
        print(f"Aufruf {func.__name__}{args}")
        ergebnis = func(*args, **kwargs)
        print(f"Ergebnis: {ergebnis}")
        return ergebnis
    return wrapper

@protokoll
def addiere(a, b):
    return a + b

summe = addiere(3, 4)
# Aufruf addiere(3, 4)
# Ergebnis: 7
print(addiere.__name__)   # addiere (ohne wraps wäre es: wrapper)

import time
import functools

def stoppuhr(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        start = time.perf_counter()
        ergebnis = func(*args, **kwargs)
        dauer = time.perf_counter() - start
        print(f"{func.__name__} brauchte {dauer:.3f} s")
        return ergebnis
    return wrapper

@stoppuhr
def summe_bis(n):
    return sum(range(n))

print(summe_bis(1_000_000))   # z. B.: summe_bis brauchte 0.012 s, dann 499999500000

