def laut(func):
    def wrapper():
        return func().upper() + "!"
    return wrapper

@laut
def sag():
    return "hi"

print(sag())

def dekorator(func):
    def wrapper(x):
        func(x)
    return wrapper

@dekorator
def doppelt(x):
    return x * 2

print(doppelt(5))

def rahmen(func):
    def wrapper():
        print("A")
        func()
        print("C")
    return wrapper

@rahmen
def mitte():
    print("B")

mitte()
